\usepackage{tikz}
\usepackage{lastpage}
\usepackage{fancyhdr}
\usepackage{graphicx}
\usepackage{xcolor}
\usepackage{tabularx}
\usepackage{emptypage}
\usepackage{array}
\usepackage{float}
\usepackage{fontspec}
\usepackage{multirow}
\usepackage{makecell}
\definecolor{municipioVerde}{RGB}{49,192,144}
\AtBeginDocument{\renewcommand{\maketitle}{}}

% === FUENTE TIMES NEW ROMAN ===
\setmainfont{Times New Roman}

% === ALINEACIÓN A LA IZQUIERDA (sin justificar) ===
\usepackage[document]{ragged2e}

% === TABLA DE CONTENIDOS: texto negro y alineado a la izquierda ===
\usepackage{tocloft}
\tocloftpagestyle{empty}
\setlength{\cftbeforetoctitleskip}{-2.5cm}
\renewcommand{\cfttoctitlefont}{\bfseries\Large\color{black}}
\renewcommand{\cftchapfont}{\color{black}\bfseries}
\renewcommand{\cftchappagefont}{\color{black}}
\renewcommand{\cftsecfont}{\color{black}}
\renewcommand{\cftsecpagefont}{\color{black}}
\renewcommand{\cftsubsecfont}{\color{black}}
\renewcommand{\cftsubsecpagefont}{\color{black}}
\renewcommand{\cftchapleader}{\cftdotfill{\cftdotsep}}


% === IMÁGENES: centradas y del mismo tamaño ===
\usepackage{etoolbox}
\usepackage[export]{adjustbox}
\let\oldincludegraphics\includegraphics
\renewcommand{\includegraphics}[2][]{\oldincludegraphics[max width=\textwidth, max height=0.80\textheight, keepaspectratio, #1]{#2}}
\AtBeginEnvironment{figure}{
  \let\oldincludegraphics\includegraphics
  \renewcommand{\includegraphics}[2][]{\oldincludegraphics[width=14cm, height=8cm, keepaspectratio=false, #1]{#2}}
}

% === CENTRAR CAPTIONS DE FIGURAS ===
\usepackage[center]{caption}

% === CÓDIGOS: no sobrepasar los límites del cuadro ===
\usepackage{fvextra}
\DefineVerbatimEnvironment{Highlighting}{Verbatim}{
  breaklines=true,
  breakanywhere=true,
  commandchars=\\\{\},
  fontsize=\small
}

% === ELIMINAR todas las líneas horizontales de \rule en el cuerpo ===
% (Quarto genera \strut\rule{} para los --- de markdown)

% === TÍTULOS: línea decorativa horizontal SOLO en capítulos ===
\usepackage{titlesec}
\titleformat{\chapter}[block]
  {\normalfont\LARGE\bfseries}
  {\thechapter.}
  {0.5em}
  {}
  [\vspace{0.5ex}\titlerule]
% === Eliminar espacio en blanco superior ===
\titlespacing*{\chapter}{0pt}{-10pt}{15pt}
\titleformat{\section}[block]
  {\normalfont\Large\bfseries}
  {\thesection}
  {1em}
  {}
\titleformat{\subsection}[block]
  {\normalfont\large\bfseries}
  {\thesubsection}
  {1em}
  {}
\titleformat{\subsubsection}[block]
  {\normalfont\normalsize\bfseries}
  {\thesubsubsection}
  {1em}
  {}

% === Eliminar border-bottom de headings (que genera Quarto) ===
\titlespacing*{\section}{0pt}{3.5ex plus 1ex minus .2ex}{2.3ex plus .2ex}
\titlespacing*{\subsection}{0pt}{3.25ex plus 1ex minus .2ex}{1.5ex plus .2ex}
\titlespacing*{\subsubsection}{0pt}{3.25ex plus 1ex minus .2ex}{1.5ex plus .2ex}


% === CAJAS DE INFORMACIÓN E IMPORTANTE ===
\usepackage[many]{tcolorbox}
\usepackage{fontawesome5}
\definecolor{infobg}{HTML}{e6f2ff}
\definecolor{espeblue}{HTML}{00529b}
\definecolor{importbg}{HTML}{fff8e6}
\definecolor{espeyellow}{HTML}{ffc107}
\newcommand{\iconInfo}{\textcolor{espeblue}{\faInfoCircle}}
\newcommand{\iconImportant}{\textcolor{espeyellow}{\faExclamationTriangle}}

\tcbuselibrary{skins,breakable}

\newtcolorbox{infobox}{
  colback=infobg, colframe=espeblue,
  leftrule=4pt, rightrule=0pt, toprule=0pt, bottomrule=0pt,
  left=6pt, right=6pt, top=4pt, bottom=4pt,
  breakable,
  before upper={\iconInfo\enspace},
  fontupper=\small
}

\newtcolorbox{importantbox}{
  colback=importbg, colframe=espeyellow,
  leftrule=4pt, rightrule=0pt, toprule=0pt, bottomrule=0pt,
  left=6pt, right=6pt, top=4pt, bottom=4pt,
  breakable,
  before upper={\iconImportant\enspace},
  fontupper=\small
}
